export async function listEnrolments(
  viewer: Viewer,
  cohortId: string,
): Promise<Enrolment[]> {
  // The viewer is a required argument rather than ambient context. A caller that
  // does not have one cannot compile, which is the only reliable way to keep an
  // unscoped query out of a codebase that four people are editing.
  const scope = scopeFor(viewer, cohortId);
  if (scope.kind === "none") return [];

  return db.enrolment.findMany({
    where: {
      cohortId,
      ...(scope.kind === "self" ? { learnerId: viewer.id } : {}),
    },
    orderBy: { createdAt: "asc" },
  });
}

for (const role of ["learner", "instructor", "administrator"] as const) {
  test(`${role} sees only their own scope of the cohort`, async ({ page }) => {
    await signInAs(page, role);
    await page.goto("/cohorts/autumn/progress");

    await expect(page.getByRole("heading", { level: 1 })).toBeVisible();

    // The negative assertion is the point. A view that renders the right thing
    // while having fetched more than it should still leaks through an export.
    for (const forbidden of forbiddenFor(role)) {
      await expect(page.getByText(forbidden)).toHaveCount(0);
    }
  });
}
